cd /app && printf '%s\n' '--- filtering path ---' && cat app/models/filter.rb 2>/dev/null || true && cat app/models/filter/fields.rb && grep -RIn --include='*.rb' -E 'Current\.account\.cards|def cards|filter.*cards|Card\.indexed_by|indexed_by\(' app/controllers app/models | sed -n '1,240p' && printf '\n--- no-due sweep query trace ---\n' && RAILS_ENV=test bin/rails runner <<'RUBY'
queries = []
ActiveRecord::Base.transaction do
  Card.update_all(last_active_at: Time.current)
  subscriber = ->(*, payload) { queries << [ payload[:name], payload[:sql] ] unless payload[:name] == "SCHEMA" }
  ActiveSupport::Notifications.subscribed(subscriber, "sql.active_record") { Card.auto_postpone_all_due }
  raise ActiveRecord::Rollback
end

puts "total queries: #{queries.size}"
queries.group_by(&:first).sort_by(&:first).each { |name, entries| puts "%3d  %s" % [ entries.size, name ] }
puts "\nCandidate card queries:"
queries.select { |name, _| name == "Card Load" }.each { |_, sql| puts sql }
RUBY

